 "content": "from collections import deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    frames = []

    # A frame is a 4-connected same-color component whose bounding box has
    # a complete, uninterrupted rectangular perimeter.
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and g[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            perimeter = all(g[r0][x] == color and g[r1][x] == color for x in range(c0, c1 + 1))
            perimeter = perimeter and all(g[y][c0] == color and g[y][c1] == color for y in range(r0, r1 + 1))
            if perimeter:
                frames.append((r0, r1, c0, c1, color))

    # Any marked interior supplies a binary pattern. Apply that pattern, in
    # the receiving frame's color, to every frame with the same inner size.
    sources = []
    for r0, r1, c0, c1, color in frames:
        pattern = [[g[y][x] != 0 for x in range(c0 + 1, c1)] for y in range(r0 + 1, r1)]
        if any(any(row) for row in pattern):
            sources.append((r1-r0-1, c1-c0-1, pattern))

    for r0, r1, c0, c1, color in frames:
        ih, iw = r1-r0-1, c1-c0-1
        for sh, sw, pattern in sources:
            if (ih, iw) == (sh, sw):
                for dy in range(ih):
                    for dx in range(iw):
                        if pattern[dy][dx]:
                            g[r0 + 1 + dy][c0 + 1 + dx] = color
                break
    return g


if __name__ == '__main__':
    pass
